style.css:
@-moz-document domain("roblox.com") {
/* Target the profile header banner container */
    .profile-header .header-banner, 
    .profile-header-container {
        position: relative !important;
        background: linear-gradient(-45deg, #ff007f, #7f00ff, #00bfff, #00ffaa) !important;
        background-size: 400% 400% !important;
        animation: gradientBG 15s ease infinite !important;
        border-radius: 12px !important;
        box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37) !important;
        border: 1px solid rgba(255, 255, 255, 0.18) !important;
        overflow: hidden !important;
        transition: transform 0.3s ease, box-shadow 0.3s ease !important;
    }

    /* Subtle hover effect for interactivity */
    .profile-header .header-banner:hover, 
    .profile-header-container:hover {
        transform: translateY(-2px) !important;
        box-shadow: 0 12px 40px 0 rgba(0, 191, 255, 0.5) !important;
    }

    /* Smooth animated neon gradient background */
    @keyframes gradientBG {
        0% { background-position: 0% 50%; }
        50% { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
    }

    /* Add a sleek gloss/glass overlay over the banner text and avatar area */
    .profile-header .profile-header-content {
        background: rgba(255, 255, 255, 0.05) !important;
        backdrop-filter: blur(8px) !important;
        -webkit-backdrop-filter: blur(8px) !important;
        border-radius: 0 0 12px 12px !important;
        border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
    }
}
